import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.BUwdTBzS.js";const _=JSON.parse('{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源优先合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。","frontmatter":{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源优先合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。"},"headers":[],"relativePath":"rules/按需-更新日志编写规范.md","filePath":"rules/按需-更新日志编写规范.md","lastUpdated":null}'),i={name:"rules/按需-更新日志编写规范.md"};function d(n,o,a,s,c,g){return e(),l("div",null,[...o[0]||(o[0]=[r('<blockquote><p>📄 本页由源文件 <code>rules/按需-更新日志编写规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-更新日志编写规范" tabindex="-1">按需-更新日志编写规范 <a class="header-anchor" href="#按需-更新日志编写规范" aria-label="Permalink to &quot;按需-更新日志编写规范&quot;">​</a></h1><blockquote><p>触发时机：撰写或修订项目 <code>changelog.md</code>（或同类版本更新说明）时。 核心：日志面向<strong>使用者</strong>，只回答「哪个组件、发生了什么、我要不要动代码」。</p></blockquote><hr><h2 id="_1-描述方式-概括式" tabindex="-1">1. 描述方式：概括式 <a class="header-anchor" href="#_1-描述方式-概括式" aria-label="Permalink to &quot;1. 描述方式：概括式&quot;">​</a></h2><ul><li><strong>一条一句话</strong>，只写「改了什么 + 影响」；根因、算法、实现手段不写进日志</li><li>「一句话」指<strong>概括方式</strong>（不展开根因与实现细节），不是「一句里塞多件事」</li><li>❌ <code>定位尺寸改用 offsetWidth / offsetHeight，因为 transform 会让 getBoundingClientRect 返回缩放后的视觉尺寸</code></li><li>✅ <code>修复缩放动画期间位置错位</code></li><li>表述落到<strong>结果层</strong>：需要读者理解内部机制才读懂的写法必须改写（❌ <code>坏键不再中断回调，其余组件主题色恢复更新</code> → ✅ <code>坏键改为忽略并告警</code>）</li><li><strong>不复述未变化的取值</strong>：默认值 / 默认行为没变时，不写「未传入时仍跟随 X（X + 24）」这类取值细节，只写「修复 X 属性不生效的问题」</li><li>根因、取舍与实现细节归 commit message / PR 描述</li><li><strong>边界</strong>：「实现细节」指内部构建 / 脚本 / 测试 / 重构等使用者不可感知的改动；<strong><code>docs/</code> 与 <code>development/</code> 的内容更新不属于此列，必须入日志</strong>（写法见 §2、§3）</li></ul><h2 id="_2-合并同源、拆开异源" tabindex="-1">2. 合并同源、拆开异源 <a class="header-anchor" href="#_2-合并同源、拆开异源" aria-label="Permalink to &quot;2. 合并同源、拆开异源&quot;">​</a></h2><ul><li><strong>判定顺序：先合并，再拆分</strong> —— 同一组件、同一工具函数族、同一能力主题的多个改动<strong>默认合并为一条</strong>（主句概括 + 括号 / 分句承接具体结果）；仅当合并后一条里仍有<strong>不相关主题</strong>时，才拆开</li><li>❌ 同组件拆两条：<code>修复 ConfigProvider 运行期增删组件键不生效</code> + <code>修复 ConfigProvider 对非本库组件键的处理</code>（读者要把同一个主语读两遍）</li><li>✅ <code>修复 [全局化配置 ConfigProvider](/guide/components/config-provider.html) 组件级主题：运行期增删组件键即时生效（新增覆盖生效、移除覆盖回退 common），theme 中的非本库组件键改为忽略并告警</code></li><li>❌ 一条里混入多个<strong>不相关主题</strong>（如「新增属性 + 构建产物调整」）—— 读者无法判断其中哪句与自己相关</li><li><strong>同一组件名 / 主题不应在相邻多条里重复出现</strong>，出现即说明该合并</li><li>合并的对象是「同源改动」，不是「为控制条数而压缩」；不同源就拆开，宁可条数多也不要堆叠</li><li>无信息量的兜底条目（如「组件库及文档代码优化」）不写 —— 但<strong>不是省略文档更新</strong>：文档更新须写明「<strong>哪类受众文档</strong>（使用者文档 <code>docs/</code> / <code>README</code>、贡献者文档 <code>development/</code> / <code>CONTRIBUTING</code>）+ <strong>变了什么主题</strong>」；<strong>不写具体文件路径</strong>，排版 / 格式类调整不展开细节（列数、格式名等）；受众不同的文档更新各自成条，禁止「优化文档」这类一句打包写法</li></ul><h2 id="_3-保留必要信息-不得过度概括" tabindex="-1">3. 保留必要信息（不得过度概括） <a class="header-anchor" href="#_3-保留必要信息-不得过度概括" aria-label="Permalink to &quot;3. 保留必要信息（不得过度概括）&quot;">​</a></h2><p>以下必须写清，压缩到看不出影响即不合格：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>破坏性变更</td><td><strong>不标注</strong>「破坏性变更」字样或用 <code>⚠️</code> 等强调标记，按动词正常起句，写明「移除了什么 / 改用什么」</td></tr><tr><td>默认值变化</td><td>写明旧值 → 新值（<strong>未变化时不复述默认值</strong>）</td></tr><tr><td>需用户改代码</td><td>写明替代写法</td></tr><tr><td>文档更新</td><td>按受众写「使用者文档 / 贡献者文档 / <code>README</code>」+ 变了什么主题；不写文件路径与排版细节，不写「优化文档」这类打包表述</td></tr></tbody></table><h2 id="_4-格式约定" tabindex="-1">4. 格式约定 <a class="header-anchor" href="#_4-格式约定" aria-label="Permalink to &quot;4. 格式约定&quot;">​</a></h2><ul><li>每条以动词开头：<code>新增</code> / <code>优化</code> / <code>增强</code> / <code>修复</code> / <code>重构</code></li><li><strong>不使用 <code>⚠️</code> 等强调标记</strong>：破坏性变更 / 默认值变化 / API 移除同样以动词正常起句，靠正文里的「原 X → 现 Y」说清影响，不加前缀、不加粗警示</li><li>组件与工具函数名用 Markdown 链接指向文档，如 <code>[文字提示 Tooltip](/guide/components/tooltip.html)</code></li><li>属性名、API、全局对象等用行内代码包裹</li><li><strong>条目数不设上限</strong>：由改动量自然决定 —— 架构重构、批量破坏性变更的大版本条目自然多，小版本自然少</li><li><strong>不为凑数拆分</strong>（一件事写成多条），<strong>也不为控数堆叠或删减信息</strong>（多件事挤进一条、砍掉必要语义）</li><li>每条长度以「一句话可读」为准：合并后的具体结果用括号 / 分句承接，<strong>并列项不超过 2 项</strong>，超过说明该概括或该拆条</li></ul><h2 id="_5-版本与历史" tabindex="-1">5. 版本与历史 <a class="header-anchor" href="#_5-版本与历史" aria-label="Permalink to &quot;5. 版本与历史&quot;">​</a></h2><ul><li>已发布版本的历史条目<strong>默认不回改</strong>，用户明确要求时才回改</li><li>新版本严格按本规范撰写，不因历史风格而妥协</li></ul><h2 id="_6-自检清单" tabindex="-1">6. 自检清单 <a class="header-anchor" href="#_6-自检清单" aria-label="Permalink to &quot;6. 自检清单&quot;">​</a></h2><ul><li>[ ] 每条能否一句话说清「改了什么 + 影响」？</li><li>[ ] 同组件 / 同工具函数族 / 同能力主题的改动是否已<strong>优先合并</strong>为一条？（先合并，再拆分）</li><li>[ ] 同一组件名 / 主题是否在相邻多条里重复出现？出现即合并</li><li>[ ] 是否存在「一条堆叠多个不相关主题」的情况？应拆为多条</li><li>[ ] 破坏性变更、默认值变化是否写明替代用法？未变化的默认值是否已删去复述？</li><li>[ ] 是否残留 <code>⚠️</code> 或「破坏性变更」前缀等强调标记？（一律不写）</li><li>[ ] 是否残留根因、算法、内部函数名，或需要读者理解内部机制才读懂的表述？</li><li>[ ] 文档更新是否按受众写明「哪类文档 + 变了什么主题」？（不写文件路径与排版细节）</li><li>[ ] 无信息量的条目是否已删除？</li><li>[ ] 是否为了控制条数而删减或模糊了必要信息？（条目数不是压缩目标）</li></ul>',17)])])}const u=t(i,[["render",d]]);export{_ as __pageData,u as default};
